create DATABASE HR_Attrition_Analytics;
use HR_Attrition_Analytics;
CREATE TABLE employees (
    EmployeeID INT PRIMARY KEY,
    Age INT,
    Gender VARCHAR(20),
    Department VARCHAR(100),
    JobRole VARCHAR(100),
    Education INT,
    EducationField VARCHAR(100),
    JobLevel INT,
    MonthlyIncome DECIMAL(10,2),
    HourlyRate DECIMAL(10,2),
    OverTime VARCHAR(20),
    JobSatisfaction INT,
    EnvironmentSatisfaction INT,
    WorkLifeBalance INT,
    YearsAtCompany INT,
    YearsInCurrentRole INT,
    YearsSinceLastPromotion INT,
    YearsWithCurrentManager INT,
    TotalWorkingYears INT,
    TrainingTimesLastYear INT,
    PerformanceRating INT,
    BusinessTravel VARCHAR(50),
    DistanceFromHome INT,
    MaritalStatus VARCHAR(30),
    JobInvolvement INT,
    Attrition VARCHAR(10),
    HireDate DATE,
    ExitDate DATE,
    City VARCHAR(100),
    State VARCHAR(100),
    AgeGroup VARCHAR(20)
);
create table departments(
departmentid int primary key,
departmentname varchar(100));

create table job_roles(
jobroleid int primary key,
jobrolename varchar(100));

USE hr_attrition_analytics;

CREATE TABLE salary_history (
    EmployeeID INT,
    HireDate DATE,
    MonthlyIncome DECIMAL(10,2),
    JobLevel INT,
    SalaryEffectiveDate DATE,
    SalaryBand VARCHAR(30),
     FOREIGN KEY (EmployeeID) REFERENCES employees(EmployeeID)
);
create table performance(
employeeid int,
performancerating int);

create table training (
employeeid int,
trainingtimeslastyear int,
trainingtype varchar (100));
