--  Query -- 
-- How many employees are there in each department --
select count(employeeid) as total_emp, department 
from employees 
group by department 
order by total_emp desc;

-- What is the overall employee attrition count and attrition rate --
SELECT
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS TotalAttrition,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) / COUNT(*),
        2
    ) AS AttritionRate
FROM employees;

-- What is the attrition count and attrition rate by department --

select department, count(*) as totalemp ,sum(case when attrition = 'yes' then 1 else 0 end ) attrition_count, 
round ( 100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) , 2) as attrition_rate 
from employees 
group by department
order by attrition_rate desc;

-- Which job roles have the highest attrition --
select jobrole, count(*) as totalemp ,sum(case when attrition = 'yes' then 1 else 0 end ) attrition_count , 
round ( 100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) , 2) as attrition_rate 
from employees 
group by jobrole
order by attrition_rate desc;

-- Does overtime have an impact on employee attrition --
select overtime, count(*) as totalemp ,sum(case when attrition = 'yes' then 1 else 0 end ) attrition_count , 
round ( 100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) , 2) as attrition_rate 
from employees 
group by overtime
order by attrition_rate desc;

-- What is the attrition rate by job level -- 
select joblevel , count(*) as totalemp , sum(case when attrition = 'yes' then 1 else 0 end) attrition_count , 
round ( 100.0 * sum(case when attrition = 'yes' then 1 else 0 end) / count(*) , 2) as attrition_rate
from employees
group by joblevel
order by joblevel;
-- What is the attrition rate by age group? -- 
select agegroup , count(*) as totalemp , sum(case when attrition = 'yes' then 1 else 0 end) attrition_count , 
round ( 100.0 * sum(case when attrition = 'yes' then 1 else 0 end) / count(*) , 2) as attrition_rate
from employees
group by agegroup
order by agegroup;

 -- What is the attrition rate by job satisfaction level -- 
 
select JobSatisfaction , count(*) as totalemp , sum(case when attrition = 'yes' then 1 else 0 end) attrition_count , 
round ( 100.0 * sum(case when attrition = 'yes' then 1 else 0 end) / count(*) , 2) as attrition_rate
from employees
group by JobSatisfaction
order by JobSatisfaction ;

-- What is the attrition rate by Work-Life Balance level? --

select worklifebalance , count(*) as totalemp, sum(case when attrition = 'yes' then 1 else 0 end ) as attrition_count,
round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ) as attrition_rate 
from employees 
group by worklifebalance
order by worklifebalance;

-- What is the attrition rate by business travel category -- 
select businesstravel,count(*) as totalemp, sum(case when attrition = 'yes' then 1 else 0 end ) as attrition_count,
round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ) as attrition_rate 
from employees 
group by businesstravel
order by attrition_rate;

-- What is the attrition rate by gender? -- 

select gender,count(*) as totalemp, sum(case when attrition = 'yes' then 1 else 0 end ) as attrition_count,
round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ) as attrition_rate 
from employees 
group by gender
order by attrition_rate;

-- What is the attrition rate by marital status --
select MaritalStatus,count(*) as totalemp, sum(case when attrition = 'yes' then 1 else 0 end ) as attrition_count,
round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ) as attrition_rate 
from employees 
group by MaritalStatus
order by attrition_rate;

-- What is the attrition rate by education level? --
select education,count(*) as totalemp, sum(case when attrition = 'yes' then 1 else 0 end ) as attrition_count,
round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ) as attrition_rate 
from employees 
group by education
order by attrition_rate;

-- What is the attrition rate by education field? -- 
select educationfield,count(*) as totalemp, sum(case when attrition = 'yes' then 1 else 0 end ) as attrition_count,
round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ) as attrition_rate 
from employees 
group by educationfield
order by attrition_rate;

-- What is the attrition rate by job involvement level? --
select JobInvolvement,count(*) as totalemp, sum(case when attrition = 'yes' then 1 else 0 end ) as attrition_count,
round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ) as attrition_rate 
from employees 
group by JobInvolvement
order by attrition_rate;

-- What is the attrition rate by performance rating? --
select PerformanceRating,count(*) as totalemp, sum(case when attrition = 'yes' then 1 else 0 end ) as attrition_count,
round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ) as attrition_rate 
from employees 
group by PerformanceRating
order by attrition_rate;
-- : What is the attrition rate by distance from home? --
select DistanceFromHome,count(*) as totalemp, sum(case when attrition = 'yes' then 1 else 0 end ) as attrition_count,
round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ) as attrition_rate 
from employees 
group by DistanceFromHome
order by attrition_rate;

-- What is the attrition rate by years at the company? -- 
select YearsAtCompany,count(*) as totalemp, sum(case when attrition = 'yes' then 1 else 0 end ) as attrition_count,
round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ) as attrition_rate 
from employees 
group by YearsAtCompany
order by YearsAtCompany;

 -- What is the attrition rate by salary band? --
 select sh.salaryband,count(*) as totalemp, sum(case when attrition = 'yes' then 1 else 0 end ) as attrition_count,
round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ) as attrition_rate 
from employees e
join salary_history sh
on e.employeeid = sh.employeeid
group by sh.salaryband
order by sh.salaryband;

-- What is the attrition rate by years in current role? -- 
select YearsInCurrentRole,count(*) as totalemp, sum(case when attrition = 'yes' then 1 else 0 end ) as attrition_count,
round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ) as attrition_rate 
from employees 
group by YearsInCurrentRole
order by YearsInCurrentRole;

-- What is the attrition rate by years since last promotion? --
SELECT
    YearsSinceLastPromotion,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY YearsSinceLastPromotion
ORDER BY YearsSinceLastPromotion;

-- What is the attrition rate by years with current manager? --
SELECT
    YearsWithCurrentManager,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY YearsWithCurrentManager
ORDER BY YearsWithCurrentManager;

-- What is the attrition rate by environment satisfaction level? --
SELECT
    EnvironmentSatisfaction,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY EnvironmentSatisfaction
ORDER BY EnvironmentSatisfaction;

-- What is the attrition rate by total working years? --

SELECT
    TotalWorkingYears,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY TotalWorkingYears
ORDER BY TotalWorkingYears;

-- What is the average monthly income by department, and how does it compare with attrition? --
select department, count(*) as totalemp, round(avg(MonthlyIncome),2) as avg_income,
SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) / COUNT(*),
        2
    ) AS AttritionRate
    from employees
    group by department
    order by avg_income desc;
    
    -- What is the average monthly income by job role, along with attrition rate? --
    select jobrole, count(*) as totalemp, round(avg(MonthlyIncome),2) as avg_income,
SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) / COUNT(*),
        2
    ) AS AttritionRate
    from employees
    group by jobrole
    order by avg_income desc;
    
    -- What is the average monthly income and attrition rate by gender? --
    SELECT
    Gender,
    COUNT(*) AS TotalEmployees,
    ROUND(AVG(MonthlyIncome), 2) AS AvgMonthlyIncome,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY Gender
ORDER BY AvgMonthlyIncome DESC;

-- Which departments have the highest number of employees who left? --
SELECT
    Department,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount
FROM employees
GROUP BY Department
ORDER BY AttritionCount DESC;

-- What is the attrition rate by department and overtime status? --
SELECT
    Department,
    OverTime,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY Department, OverTime
ORDER BY Department, AttritionRate DESC;
 -- What is the attrition rate by department and job level? --
 SELECT
    Department,
    joblevel,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY Department, joblevel
ORDER BY Department, AttritionRate DESC;

-- Which employees have the highest monthly income? -- 

SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    JobLevel
FROM employees
ORDER BY MonthlyIncome DESC
LIMIT 10;

-- Which employees have been with the company the longest? -- 
SELECT
    EmployeeID,
    Department,
    JobRole,
    YearsAtCompany,
    YearsInCurrentRole,
    YearsSinceLastPromotion
FROM employees
order by  YearsAtCompany desc 
limit 10;

-- What are the top 10 employees with the highest salary but who also have attrition = Yes? --

select employeeid, department,jobrole,monthlyincome,joblevel,yearsatcompany
from employees
where attrition = 'yes'
order by monthlyincome desc
limit 10;

-- What is the attrition rate for employees with different training frequencies? --
SELECT
    TrainingTimesLastYear,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY TrainingTimesLastYear
ORDER BY TrainingTimesLastYear;

-- Attrition by Salary & Overtime --

SELECT
    sh.SalaryBand,
    e.OverTime,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN e.Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN e.Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees e
JOIN salary_history sh
    ON e.EmployeeID = sh.EmployeeID
GROUP BY
    sh.SalaryBand,
    e.OverTime
ORDER BY
    sh.SalaryBand,
    e.OverTime;
    
    -- Attrition by Department + Job Role --
    SELECT
    Department,
    JobRole,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY
    Department,
    JobRole
ORDER BY
    Department,
    AttritionRate DESC;
    
    -- Attrition by Department + Job Satisfaction --
    
    select department, jobsatisfaction, count(*) as empcount, 
    sum(case when attrition = 'yes' then 1 else 0 end) as attrition_count,
    round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end)/count(*) ,2)as attritionrate
    from employees
    group by department, jobsatisfaction
    order by department, attritionrate desc ;
    
    -- Attrition by Department + Work-Life Balance --
    
    select department, worklifebalance, count(*) as empcount, 
    sum(case when attrition = 'yes' then 1 else 0 end) as attrition_count,
    round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end)/count(*) ,2)as attritionrate
    from employees
    group by department, worklifebalance
    order by department, attritionrate desc ;
    
    -- Attrition by Department + Business Travel --
    select department, BusinessTravel, count(*) as empcount, 
    sum(case when attrition = 'yes' then 1 else 0 end) as attrition_count,
    round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end)/count(*) ,2)as attritionrate
    from employees
    group by department, BusinessTravel
    order by department, BusinessTravel ;
    -- Attrition by Department + Performance Rating --
    SELECT
    Department,
    PerformanceRating,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY
    Department,
    PerformanceRating
ORDER BY
    Department,
    PerformanceRating;
    
    
    -- Attrition by Department + Education Field --
    SELECT
    Department,
    EducationField,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY
    Department,
    EducationField
ORDER BY
    Department,
    AttritionRate DESC;
    
    -- Attrition by Department + Job Involvement --
    SELECT
    Department,
    JobInvolvement,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY
    Department,
    JobInvolvement
ORDER BY
    Department,
    JobInvolvement;
    -- Attrition by Department + Environment Satisfaction -- 
    SELECT
    Department,
    EnvironmentSatisfaction,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY
    Department,
    EnvironmentSatisfaction
ORDER BY
    Department,
    EnvironmentSatisfaction;
    
    -- Attrition by Department + Distance from Home --
    SELECT
    Department,
    CASE
        WHEN DistanceFromHome <= 5 THEN 'Near (0-5)'
        WHEN DistanceFromHome <= 15 THEN 'Medium (6-15)'
        WHEN DistanceFromHome <= 30 THEN 'Far (16-30)'
        ELSE 'Very Far (31+)'
    END AS DistanceGroup,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY
    Department,
    DistanceGroup
ORDER BY
    Department,
    AttritionRate DESC;
    
    -- Attrition by Department + Years at Company --
    select department, 
    case 
    when yearsatcompany <= 2 then '0-2 years'
    when yearsatcompany <=5 then '3-5 years'
    when yearsatcompany <= 10 then '6-10 years'
    when yearsatcompany <= 15 then '11-15 years'
    else '16+ years' 
    end as yeargroup,
    count(*) as emp_count,
    sum(case when attrition = 'yes' then 1 else 0 end )as attritioncount,
    round(100.0 * sum(case when attrition = 'yes' then 1 else 0 end ) / count(*) ,2) as attritionrate
    from employees
    group by department, yeargroup
    order by attritionrate,yeargroup desc;
    
    -- Attrition by Job Role + Overtime --
    SELECT
    JobRole,
    OverTime,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY
    JobRole,
    OverTime
ORDER BY
    JobRole,
    AttritionRate DESC;
    
    -- Attrition by Job Role + Job Level --
    SELECT
    JobRole,
    JobLevel,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY
    JobRole,
    JobLevel
ORDER BY
    JobRole,
    JobLevel;
    
    -- Attrition by Job Role + Job Satisfaction --
    SELECT
    JobRole,
    JobSatisfaction,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY
    JobRole,
    JobSatisfaction
ORDER BY
    JobRole,
    JobSatisfaction;
    
     -- Attrition by Job Role + Work-Life Balance--
     SELECT
    JobRole,
    WorkLifeBalance,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY
    JobRole,
    WorkLifeBalance
ORDER BY
    JobRole,
    WorkLifeBalance;
    -- Attrition by Job Role + Business Travel --
    SELECT
    JobRole,
    BusinessTravel,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(
        100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees
GROUP BY
    JobRole,
    BusinessTravel
ORDER BY
    JobRole,
    BusinessTravel;
    
    -- Rank Job Roles by Attrition Rate --
    WITH JobRoleAttrition AS (
    SELECT
        JobRole,
        COUNT(*) AS TotalEmployees,
        SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
        ROUND(
            100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
            / COUNT(*),
            2
        ) AS AttritionRate
        from employees
        group by jobrole)
        select jobrole,totalemployees,attritioncount,attritionrate, 
        rank () over ( order by attritionrate desc) as rnk 
        from jobroleattrition 
        order by rnk;
        
        --  Department-wise Attrition Rank -- 
         WITH departmentattrition AS (
    SELECT
        department,
        COUNT(*) AS TotalEmployees,
        SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
        ROUND(
            100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
            / COUNT(*),
            2
        ) AS AttritionRate
        from employees
        group by department)
        select department, attritioncount,attritionrate,
    rank() over (order by attritionrate) as rnk
    from departmentattrition 
    order by rnk ;
    
    -- Highest-Paid Employees Within Each Department -- 
    with highpaidemployee as 
    (select employeeid,department,jobrole,monthlyincome,attrition ,
    row_number() over ( partition by  department order by monthlyincome ) as paidemp from employees)
    select department, paidemp,monthlyincome 
    from highpaidemployee
    where paidemp <= 3
    order by department, paidemp;
    
    -- Top 3 Highest-Attrition Job Roles --
    WITH JobRoleAttrition AS (
    SELECT
        JobRole,
        COUNT(*) AS TotalEmployees,
        SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
        ROUND(
            100.0 * SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END)
            / COUNT(*),
            2
        ) AS AttritionRate
    FROM employees
    GROUP BY JobRole
),

RankedRoles AS (
    SELECT
        JobRole,
        TotalEmployees,
        AttritionCount,
        AttritionRate,
        DENSE_RANK() OVER (
            ORDER BY AttritionRate DESC
        ) AS AttritionRank
    FROM JobRoleAttrition
)

SELECT
    JobRole,
    TotalEmployees,
    AttritionCount,
    AttritionRate,
    AttritionRank
FROM RankedRoles
WHERE AttritionRank <= 3
ORDER BY AttritionRank;

-- Employees Earning Above Their Department Average --

WITH DepartmentSalary AS (
    SELECT
        Department,
        AVG(MonthlyIncome) AS AvgDepartmentSalary
    FROM employees
    GROUP BY Department
)

SELECT
    e.EmployeeID,
    e.Department,
    e.JobRole,
    e.MonthlyIncome,
    ROUND(ds.AvgDepartmentSalary, 2) AS AvgDepartmentSalary,
    ROUND(e.MonthlyIncome - ds.AvgDepartmentSalary, 2) AS SalaryDifference
FROM employees e
JOIN DepartmentSalary ds
    ON e.Department = ds.Department
WHERE e.MonthlyIncome > ds.AvgDepartmentSalary
ORDER BY
    e.Department,
    e.MonthlyIncome DESC;
    
    -- Employees Earning Above Their Job Role Average --
    WITH JobRoleSalary AS (
    SELECT
        JobRole,
        AVG(MonthlyIncome) AS AvgRoleSalary
    FROM employees
    GROUP BY JobRole
)

SELECT
    e.EmployeeID,
    e.JobRole,
    e.Department,
    e.MonthlyIncome,
    ROUND(jrs.AvgRoleSalary, 2) AS AvgRoleSalary,
    ROUND(e.MonthlyIncome - jrs.AvgRoleSalary, 2) AS SalaryDifference
FROM employees e
JOIN JobRoleSalary jrs
    ON e.JobRole = jrs.JobRole
WHERE e.MonthlyIncome > jrs.AvgRoleSalary
ORDER BY
    e.JobRole,
    e.MonthlyIncome DESC;
    
    -- Department Salary Ranking --
    WITH rankemployee as(
    select employeeid,department,jobrole,monthlyincome,attrition, 
    dense_rank() over ( partition by department order by monthlyincome) as salaryrank 
    from employees
    )
    select  employeeid,department,jobrole,monthlyincome,attrition, salaryrank 
    from rankemployee
    where salaryrank <=3
    order  by department,salaryrank,monthlyincome desc;
    
    -- Salary Rank and Attrition Status --
    WITH RankedEmployees AS (
    SELECT
        EmployeeID,
        Department,
        JobRole,
        MonthlyIncome,
        Attrition,
        DENSE_RANK() OVER (
            PARTITION BY Department
            ORDER BY MonthlyIncome DESC
        ) AS SalaryRank
    FROM employees
)

SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    Attrition,
    SalaryRank
FROM RankedEmployees
ORDER BY
    Department,
    SalaryRank;
    
    -- Employees with Salary Above Department Average + Attrition --
    WITH DepartmentSalary AS (
    SELECT
        Department,
        AVG(MonthlyIncome) AS AvgDepartmentSalary
    FROM employees
    GROUP BY Department
)

SELECT
    e.EmployeeID,
    e.Department,
    e.JobRole,
    e.MonthlyIncome,
    ROUND(ds.AvgDepartmentSalary, 2) AS AvgDepartmentSalary,
    ROUND(e.MonthlyIncome - ds.AvgDepartmentSalary, 2) AS SalaryDifference,
    e.Attrition
FROM employees e
JOIN DepartmentSalary ds
    ON e.Department = ds.Department
WHERE e.MonthlyIncome > ds.AvgDepartmentSalary
ORDER BY
    e.Department,
    e.MonthlyIncome DESC;
    
    -- Top 5 Highest-Paid Employees Who Left --
    SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    YearsAtCompany,
    OverTime,
    Attrition
FROM (
    SELECT
        EmployeeID,
        Department,
        JobRole,
        MonthlyIncome,
        YearsAtCompany,
        OverTime,
        Attrition,
        ROW_NUMBER() OVER (
            ORDER BY MonthlyIncome DESC
        ) AS SalaryRank
    FROM employees
    WHERE Attrition = 'Yes'
) AS RankedEmployees
WHERE SalaryRank <= 5
ORDER BY MonthlyIncome DESC;

-- Attrition Rate by Salary Band --
SELECT
    sh.SalaryBand,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN e.Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(AVG(e.MonthlyIncome), 2) AS AverageSalary,
    ROUND(
        100.0 * SUM(CASE WHEN e.Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees e
JOIN salary_history sh
    ON e.EmployeeID = sh.EmployeeID
GROUP BY sh.SalaryBand
ORDER BY AttritionRate DESC;

-- Attrition by Salary Band + Overtime --
SELECT
    sh.SalaryBand,
    e.OverTime,
    COUNT(*) AS TotalEmployees,
    SUM(CASE WHEN e.Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount,
    ROUND(AVG(e.MonthlyIncome), 2) AS AverageSalary,
    ROUND(
        100.0 * SUM(CASE WHEN e.Attrition = 'Yes' THEN 1 ELSE 0 END)
        / COUNT(*),
        2
    ) AS AttritionRate
FROM employees e
JOIN salary_history sh
    ON e.EmployeeID = sh.EmployeeID
GROUP BY
    sh.SalaryBand,
    e.OverTime
ORDER BY
    sh.SalaryBand,
    e.OverTime;
    
    -- Department Salary Ranking with Attrition --
    WITH RankedEmployees AS (
    SELECT
        EmployeeID,
        Department,
        JobRole,
        MonthlyIncome,
        Attrition,
        DENSE_RANK() OVER (
            PARTITION BY Department
            ORDER BY MonthlyIncome DESC
        ) AS SalaryRank
    FROM employees
)

SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    Attrition,
    SalaryRank
FROM RankedEmployees
WHERE SalaryRank <= 5
ORDER BY
    Department,
    SalaryRank,
    MonthlyIncome DESC;
    
    -- CTEs & Subqueries --
    -- Department-wise Average Salary vs Company Average --
    
    SELECT
    Department,
    ROUND(AVG(MonthlyIncome), 2) AS DepartmentAvgSalary,
    ROUND(
        (SELECT AVG(MonthlyIncome) FROM employees),
        2
    ) AS CompanyAvgSalary,
    ROUND(
        AVG(MonthlyIncome) -
        (SELECT AVG(MonthlyIncome) FROM employees),
        2
    ) AS DifferenceFromCompanyAvg
FROM employees
GROUP BY Department
ORDER BY DifferenceFromCompanyAvg DESC;

-- Employees Earning More Than Company Average --
SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    Attrition
FROM employees
WHERE MonthlyIncome > (
    SELECT AVG(MonthlyIncome)
    FROM employees
)
ORDER BY MonthlyIncome DESC;

-- Employees Earning Below Their Department Averag --
WITH DepartmentSalary AS (
    SELECT
        Department,
        AVG(MonthlyIncome) AS AvgDepartmentSalary
    FROM employees
    GROUP BY Department
)

SELECT
    e.EmployeeID,
    e.Department,
    e.JobRole,
    e.MonthlyIncome,
    ROUND(ds.AvgDepartmentSalary, 2) AS AvgDepartmentSalary,
    ROUND(
        e.MonthlyIncome - ds.AvgDepartmentSalary,
        2
    ) AS SalaryDifference,
    e.Attrition
FROM employees e
JOIN DepartmentSalary ds
    ON e.Department = ds.Department
WHERE e.MonthlyIncome < ds.AvgDepartmentSalary
ORDER BY
    e.Department,
    e.MonthlyIncome;
    -- Employees with Above-Average Salary and Attrition --
    SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    YearsAtCompany,
    OverTime,
    Attrition
FROM employees
WHERE MonthlyIncome > (
    SELECT AVG(MonthlyIncome)
    FROM employees
)
AND Attrition = 'Yes'
ORDER BY MonthlyIncome DESC;

-- Employees with Below-Average Salary and Attrition -- 
SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    YearsAtCompany,
    OverTime,
    Attrition
FROM employees
WHERE MonthlyIncome < (
    SELECT AVG(MonthlyIncome)
    FROM employees
)
AND Attrition = 'Yes'
ORDER BY MonthlyIncome ASC;

-- Employees with the Same Salary --
SELECT
    e1.EmployeeID AS Employee1,
    e1.Department AS Department1,
    e1.JobRole AS JobRole1,
    e1.MonthlyIncome,
    e2.EmployeeID AS Employee2,
    e2.Department AS Department2,
    e2.JobRole AS JobRole2
FROM employees e1
JOIN employees e2
    ON e1.MonthlyIncome = e2.MonthlyIncome
    AND e1.EmployeeID < e2.EmployeeID
ORDER BY
    e1.MonthlyIncome DESC;
    
    -- Employees with the Same Job Role and Salary --
    select e1.employeeid as employee1,e1.jobrole,e1.monthlyincome,e1.department as department1,e1.employeeid as employee2,e1.department as department2
    from employees e1
    join employees e2 on 
    e1.jobrole = e2.jobrole 
    and e1.monthlyincome = e2.monthlyincome
    and e1.employeeid < e2.employeeid
    order by e1.jobrole, e1.monthlyincome desc;
    
    -- Window Functions --
    -- Department-wise Salary Rank --
    WITH RankedEmployees AS (
    SELECT
        EmployeeID,
        Department,
        JobRole,
        MonthlyIncome,
        Attrition,
        ROW_NUMBER() OVER (
            PARTITION BY Department
            ORDER BY MonthlyIncome DESC
        ) AS SalaryRank
    FROM employees
)

SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    Attrition,
    SalaryRank
FROM RankedEmployees
WHERE SalaryRank <= 5
ORDER BY
    Department,
    SalaryRank;
    
    -- Salary Rank --
    SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    Attrition,
    RANK() OVER (
        PARTITION BY Department
        ORDER BY MonthlyIncome DESC
    ) AS SalaryRank
FROM employees
ORDER BY
    Department,
    SalaryRank;
    
    -- Department Salary Ranking --
    SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    Attrition,
    DENSE_RANK() OVER (
        PARTITION BY Department
        ORDER BY MonthlyIncome DESC
    ) AS SalaryRank
FROM employees
ORDER BY
    Department,
    SalaryRank;
    
    -- Department Salary Percentile --
    SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    Attrition,
    ROUND(
        PERCENT_RANK() OVER (
            PARTITION BY Department
            ORDER BY MonthlyIncome
        ),
        2
    ) AS SalaryPercentile
FROM employees
ORDER BY
    Department,
    SalaryPercentile;
    
    -- Salary Quartile by Department --
    SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    Attrition,
    NTILE(4) OVER (
        PARTITION BY Department
        ORDER BY MonthlyIncome
    ) AS SalaryQuartile
FROM employees
ORDER BY
    Department,
    SalaryQuartile,
    MonthlyIncome;
    
    -- Running Salary Average by Department --
    SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    ROUND(
        AVG(MonthlyIncome) OVER (
            PARTITION BY Department
            ORDER BY MonthlyIncome
            ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        ),
        2
    ) AS RunningAvgSalary
FROM employees
ORDER BY
    Department,
    MonthlyIncome;
    
    -- Department Salary Difference from Previous Employee --
    SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    LAG(MonthlyIncome) OVER (
        PARTITION BY Department
        ORDER BY MonthlyIncome
    ) AS PreviousSalary,
    MonthlyIncome -
    LAG(MonthlyIncome) OVER (
        PARTITION BY Department
        ORDER BY MonthlyIncome
    ) AS SalaryDifference
FROM employees
ORDER BY
    Department,
    MonthlyIncome;
    
    -- Next Employee Salary --
    SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    LEAD(MonthlyIncome) OVER (
        PARTITION BY Department
        ORDER BY MonthlyIncome
    ) AS NextSalary,
    LEAD(MonthlyIncome) OVER (
        PARTITION BY Department
        ORDER BY MonthlyIncome
    ) - MonthlyIncome AS SalaryDifference
FROM employees
ORDER BY
    Department,
    MonthlyIncome;
    
    -- Department Salary Difference --
    SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    FIRST_VALUE(MonthlyIncome) OVER (
        PARTITION BY Department
        ORDER BY MonthlyIncome DESC
    ) AS HighestDepartmentSalary,
    FIRST_VALUE(MonthlyIncome) OVER (
        PARTITION BY Department
        ORDER BY MonthlyIncome DESC
    ) - MonthlyIncome AS DifferenceFromHighestSalary
FROM employees
ORDER BY
    Department,
    MonthlyIncome DESC;

 -- Lowest Salary vs Employee Salary --
 SELECT
    EmployeeID,
    Department,
    JobRole,
    MonthlyIncome,
    LAST_VALUE(MonthlyIncome) OVER (
        PARTITION BY Department
        ORDER BY MonthlyIncome
        ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
    ) AS HighestDepartmentSalary,
    MonthlyIncome -
    LAST_VALUE(MonthlyIncome) OVER (
        PARTITION BY Department
        ORDER BY MonthlyIncome
        ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING
    ) AS DifferenceFromHighestSalary
FROM employees
ORDER BY
    Department,
    MonthlyIncome;
    
    -- Department Attrition Rate vs Company Attrition Rate --
    WITH DepartmentStats AS (
    SELECT
        Department,
        COUNT(*) AS TotalEmployees,
        SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount
    FROM employees
    GROUP BY Department
),

CompanyStats AS (
    SELECT
        COUNT(*) AS TotalEmployees,
        SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount
    FROM employees
)

SELECT
    ds.Department,
    ds.TotalEmployees,
    ds.AttritionCount,
    ROUND(
        100.0 * ds.AttritionCount / ds.TotalEmployees,
        2
    ) AS DepartmentAttritionRate,
    ROUND(
        100.0 * cs.AttritionCount / cs.TotalEmployees,
        2
    ) AS CompanyAttritionRate,
    ROUND(
        (100.0 * ds.AttritionCount / ds.TotalEmployees)
        -
        (100.0 * cs.AttritionCount / cs.TotalEmployees),
        2
    ) AS DifferenceFromCompanyRate
FROM DepartmentStats ds
CROSS JOIN CompanyStats cs
ORDER BY DifferenceFromCompanyRate DESC;

-- Attrition Rate by Job Level vs Company Rate --
WITH OvertimeStats AS (
    SELECT
        OverTime,
        COUNT(*) AS TotalEmployees,
        SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount
    FROM employees
    GROUP BY OverTime
),

CompanyStats AS (
    SELECT
        COUNT(*) AS TotalEmployees,
        SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount
    FROM employees
)

SELECT
    os.OverTime,
    os.TotalEmployees,
    os.AttritionCount,
    ROUND(
        100.0 * os.AttritionCount / os.TotalEmployees,
        2
    ) AS OvertimeAttritionRate,
    ROUND(
        100.0 * cs.AttritionCount / cs.TotalEmployees,
        2
    ) AS CompanyAttritionRate,
    ROUND(
        (100.0 * os.AttritionCount / os.TotalEmployees)
        -
        (100.0 * cs.AttritionCount / cs.TotalEmployees),
        2
    ) AS DifferenceFromCompanyRate
FROM OvertimeStats os
CROSS JOIN CompanyStats cs
ORDER BY
    os.OverTime;
    
    -- Attrition Rate by Age Group vs Company Rate --
    WITH AgeGroupStats AS (
    SELECT
        AgeGroup,
        COUNT(*) AS TotalEmployees,
        SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount
    FROM employees
    GROUP BY AgeGroup
),

CompanyStats AS (
    SELECT
        COUNT(*) AS TotalEmployees,
        SUM(CASE WHEN Attrition = 'Yes' THEN 1 ELSE 0 END) AS AttritionCount
    FROM employees
)

SELECT
    ags.AgeGroup,
    ags.TotalEmployees,
    ags.AttritionCount,
    ROUND(
        100.0 * ags.AttritionCount / ags.TotalEmployees,
        2
    ) AS AgeGroupAttritionRate,
    ROUND(
        100.0 * cs.AttritionCount / cs.TotalEmployees,
