    ) AS CompanyAttritionRate,
    ROUND(
        (100.0 * ags.AttritionCount / ags.TotalEmployees)
        -
        (100.0 * cs.AttritionCount / cs.TotalEmployees),
        2
    ) AS DifferenceFromCompanyRate
FROM AgeGroupStats ags
