-- Missing Values Check --
SELECT
    SUM(CASE WHEN EmployeeID IS NULL OR EmployeeID = '' THEN 1 ELSE 0 END) AS MissingEmployeeID,
    SUM(CASE WHEN Department IS NULL OR Department = '' THEN 1 ELSE 0 END) AS MissingDepartment,
    SUM(CASE WHEN JobRole IS NULL OR JobRole = '' THEN 1 ELSE 0 END) AS MissingJobRole,
    SUM(CASE WHEN MonthlyIncome IS NULL THEN 1 ELSE 0 END) AS MissingMonthlyIncome,
    SUM(CASE WHEN Attrition IS NULL OR Attrition = '' THEN 1 ELSE 0 END) AS MissingAttrition,
    SUM(CASE WHEN HireDate IS NULL THEN 1 ELSE 0 END) AS MissingHireDate
FROM employees;

